/**
 * Inputs for the roadmap import characterization test. The expected output of
 * each one lives in `roadmapImportExpected.json` and was recorded from the
 * original hand-written validator before it was migrated to Zod.
 */
type Case = [name: string, input: unknown]

const mod = (over: Record<string, unknown> = {}) => ({ title: 'Módulo', ...over })
const rm = (over: Record<string, unknown> = {}) => ({ title: 'Ruta', modules: [mod()], ...over })
const withModule = (over: Record<string, unknown>) => rm({ modules: [mod(over)] })
const q = (over: Record<string, unknown> = {}) => ({ question: 'Pregunta', answer: 'A', options: ['A', 'B'], ...over })
const withQuiz = (...questions: unknown[]) => withModule({ quiz: questions })
const long = (n: number) => 'x'.repeat(n)
const many = (n: number, make: (i: number) => unknown = i => `item ${i}`) => Array.from({ length: n }, (_, i) => make(i))

